  model, feature_schema, vocabulary_or_hash_config, normalizer,
  user_encoder_version, creative_encoder_version, calibrator,
  allowed_freshness, fallback_policy, evaluation_manifest
}
features = fetch_batch(request, deadline=request.deadline)
validate_schema_and_embedding_versions(features, bundle)
